const app=document.querySelector('#app'), dialog=document.querySelector('#dialog'), toastEl=document.querySelector('#toast');
const PERMISSIONS=[['view_attendance','View attendance'],['mark_attendance','Mark attendance'],['edit_attendance','Correct attendance'],['view_assigned_subjects','View assigned subjects'],['manage_assigned_subjects','Manage assigned subjects'],['view_assigned_classes','View assigned classes'],['view_student_info','View relevant student information'],['view_attendance_history','View attendance history'],['view_routines','View class routines'],['manage_routines','Manage class routines'],['view_holidays','View holidays']];
const state={user:null,csrf:'',view:'overview',data:null,routinePeriods:null,routineWeekday:null,theme:localStorage.getItem('edutrack-theme')||'light'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=v=>v?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeZone:'Asia/Kolkata'}).format(new Date(`${v}T00:00:00+05:30`)):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const pct=(n,d)=>d?Math.round(n/d*1000)/10:0;
function toast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),3200)}
async function api(path,options={}){const method=(options.method||'GET').toUpperCase();const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};if(method!=='GET'&&method!=='HEAD'&&state.csrf)headers['X-CSRF-Token']=state.csrf;const res=await fetch(path,{...options,method,headers,credentials:'same-origin',body:options.body?JSON.stringify(options.body):undefined});const data=await res.json().catch(()=>({error:'The server returned an invalid response.'}));if(!res.ok){if(res.status===401&&state.user){state.user=null;state.csrf='';renderLogin()}throw new Error(data.error||`Request failed (${res.status})`)}return data}
const button=(label,action,cls='soft',extra='')=>`<button class="button ${cls} ${extra}" data-action="${esc(action)}">${esc(label)}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const empty=(title,body='There is nothing here yet.')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(body)}</div>`;
function setLoading(text='Loading…'){app.innerHTML=`<div class="loading"><span class="spinner"></span><span>${esc(text)}</span></div>`}
function applyTheme(){document.documentElement.dataset.theme=state.theme==='dark'?'dark':'';document.querySelector('#theme-toggle').textContent=state.theme==='dark'?'☀':'◐'}
function field(name,label,type='text',value='',attrs=''){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${attrs}></label>`}
function selectField(name,label,options,value='',attrs=''){return `<label class="field">${esc(label)}<select name="${esc(name)}" ${attrs}><option value="">Select…</option>${options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`}
function textareaField(name,label,value='',attrs=''){return `<label class="field">${esc(label)}<textarea name="${esc(name)}" ${attrs}>${esc(value)}</textarea></label>`}
function modalForm(title,content,submit='Save',danger=false){dialog.innerHTML=`<form class="dialog-inner"><div class="dialog-head"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-action="close-dialog" aria-label="Close">×</button></div><div class="dialog-content">${content}</div><div class="dialog-actions"><button type="button" class="button quiet" data-action="close-dialog">Cancel</button><button class="button ${danger?'danger':'primary'}">${esc(submit)}</button></div></form>`;dialog.showModal();return new Promise(resolve=>{let settled=false;const done=value=>{if(!settled){settled=true;resolve(value)}};dialog.addEventListener('close',()=>done(null),{once:true});dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();done(Object.fromEntries(new FormData(e.currentTarget)));dialog.close()},{once:true})})}
function confirmDialog(title,message,submit='Continue',danger=false){return modalForm(title,`<p class="subtle">${esc(message)}</p>`,submit,danger).then(v=>v)}
function selectAuthMode(mode){document.querySelectorAll('[data-auth-mode]').forEach(b=>b.setAttribute('aria-current',b.dataset.authMode===mode?'page':'false'));const panel=document.querySelector('#auth-panel');if(mode==='register'){panel.innerHTML=`<p class="mobile-note">Register a college workspace and create its first OWNER account.</p><form id="register-form" class="form">${field('collegeName','College name','text','','required maxlength="180" autocomplete="organization"')}${field('fullName','Owner full name','text','','required maxlength="180" autocomplete="name"')}${field('username','Owner username','text','','required minlength="3" maxlength="64" autocomplete="username"')}${field('password','Password','password','','required minlength="12" maxlength="200" autocomplete="new-password"')}<button class="button primary full">Register your college</button></form>`;panel.querySelector('#register-form').addEventListener('submit',registerCollege);return}const studentMode=mode==='community';panel.innerHTML=`<p class="mobile-note">${studentMode?'Students and moderators use the same sign-in. Students also enter their individual access code.':'Sign in to your college OWNER workspace. Your role is verified by Edutrack.'}</p><form id="login-form" class="form">${field('username','Username','text','','autocomplete="username" required')}${field('password','Password','password','','autocomplete="current-password" required')}${studentMode?field('accessCode','Student access code (students only)','password','','autocomplete="one-time-code"'):''}<button class="button primary full">Sign in</button></form>`;panel.querySelector('#login-form').addEventListener('submit',login)}
function renderLogin(){document.querySelector('#identity').hidden=true;document.querySelector('#logout').hidden=true;document.querySelector('#college-name').textContent='College academic platform';document.querySelector('#college-name').hidden=false;app.innerHTML=`<div class="login-wrap"><section class="login-card"><p class="eyebrow">College academic platform</p><h1>Edutrack</h1><p class="subtle">Secure attendance and academic management for your college.</p><nav class="nav auth-options" aria-label="Sign-in options"><button data-auth-mode="owner" aria-current="page">OWNER SIGN IN</button><button data-auth-mode="community" aria-current="false">STUDENT / MODERATOR</button><button data-auth-mode="register" aria-current="false">REGISTER COLLEGE</button></nav><div id="auth-panel"></div><details id="owner-recovery" style="margin-top:18px"><summary>Owner account recovery</summary><p class="mobile-note">Use the recovery code issued when the college was registered. Recovery revokes active owner sessions.</p><form id="recovery-form" class="form">${field('username','Owner username','text','','required autocomplete="username"')}${field('recoveryKey','Owner recovery code','password','','required autocomplete="off"')}${field('password','New password','password','','required minlength="12" autocomplete="new-password"')}<button class="button soft full">Reset owner password</button></form></details></section></div>`;document.querySelectorAll('[data-auth-mode]').forEach(b=>b.addEventListener('click',()=>selectAuthMode(b.dataset.authMode)));document.querySelector('#recovery-form').addEventListener('submit',recoverOwner);selectAuthMode('owner')}
async function login(e){e.preventDefault();const form=e.currentTarget;const b=form.querySelector('button[type=submit],button:not([type])');b.disabled=true;try{const creds=Object.fromEntries(new FormData(form));const out=await api('/api/login',{method:'POST',body:creds});state.user=out.user;state.csrf=out.csrf;await loadDashboard()}catch(err){toast(err.message)}finally{b.disabled=false}}
async function showRecoveryCode(code){dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2>Save your owner recovery code</h2></div><div class="dialog-content"><p>This code is shown once. Store it somewhere private so you can recover this college OWNER account.</p><label class="field">Recovery code<input id="recovery-code-value" readonly value="${esc(code)}"></label><div class="row-actions"><button id="copy-recovery-code" class="button soft" type="button">Copy code</button></div></div><div class="dialog-actions"><button id="recovery-code-saved" class="button primary" type="button">I saved this code</button></div></div>`;dialog.showModal();dialog.querySelector('#recovery-code-value').addEventListener('focus',e=>e.target.select());dialog.querySelector('#copy-recovery-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(code);toast('Recovery code copied')}catch{dialog.querySelector('#recovery-code-value').select();toast('Select and copy the recovery code')}});return new Promise(resolve=>{dialog.addEventListener('cancel',e=>e.preventDefault(),{once:true});dialog.querySelector('#recovery-code-saved').addEventListener('click',()=>{dialog.close();resolve()},{once:true})})}
async function registerCollege(e){e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit],button:not([type])');b.disabled=true;try{const out=await api('/api/register-college',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});state.user=out.user;state.csrf=out.csrf;await showRecoveryCode(out.recoveryCode);await loadDashboard()}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=false}}
async function recoverOwner(e){e.preventDefault();try{const out=await api('/api/setup/recover-owner',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});toast(out.message);e.currentTarget.reset()}catch(err){toast(err.message)}}
async function loadDashboard(){setLoading('Loading your dashboard…');try{const out=await api('/api/me');state.user=out.user;state.csrf=out.csrf;state.routinePeriods=null;state.routineWeekday=null;document.querySelector('#identity').textContent=out.user.fullName;document.querySelector('#identity').hidden=false;const collegeName=document.querySelector('#college-name');collegeName.textContent=out.user.collegeName||'College workspace';collegeName.hidden=!out.user.collegeName;document.querySelector('#logout').hidden=false;render()}catch(e){state.user=null;state.csrf='';renderLogin()}}
async function boot(){applyTheme();try{await loadDashboard()}catch{renderLogin()}}
function navItems(){if(state.user.role==='OWNER')return [['overview','Overview'],['students','Students'],['moderators','Moderators'],['academics','Academics'],['attendance','Attendance'],['routines','Class routine'],['holidays','Holidays'],['reports','Reports & audit'],['security','Security']];if(state.user.role==='STUDENT')return [['overview','Overview'],['history','Attendance history'],['routine','My timetable'],['holidays','Holidays']];const p=new Set(state.user.permissions||[]),items=[['overview','Overview']];if(p.has?.('view_attendance')||state.user.permissions?.includes('view_attendance'))items.push(['attendance','Attendance']);if(state.user.permissions?.some(x=>['view_assigned_subjects','manage_assigned_subjects'].includes(x)))items.push(['subjects','Subjects']);if(state.user.permissions?.includes('view_attendance_history'))items.push(['history','Attendance history']);if(state.user.permissions?.some(x=>['view_routines','manage_routines'].includes(x)))items.push(['routine','Class routine']);if(state.user.permissions?.includes('view_holidays'))items.push(['holidays','Holidays']);return items}
async function render(){if(!state.user)return renderLogin();applyTheme();const items=navItems();if(!items.some(x=>x[0]===state.view))state.view='overview';app.innerHTML=`<div class="welcome"><div><p class="eyebrow">${state.user.role==='OWNER'?'Administration':state.user.role==='MODERATOR'?'Teaching workspace':'Student portal'}</p><h1>${esc(greeting())}</h1><p>${esc(state.user.fullName)} · <span class="role-badge">${esc(state.user.role)}</span></p></div>${state.user.role==='STUDENT'?badge('READ ONLY'):''}</div><nav class="nav" aria-label="Dashboard sections">${items.map(([key,name])=>`<button data-view="${key}" aria-current="${state.view===key?'page':'false'}">${esc(name)}</button>`).join('')}</nav><section id="view-content">${viewLoading()}</section>`;app.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{state.view=b.dataset.view;render()}));try{await renderView()}catch(e){document.querySelector('#view-content').innerHTML=`<div class="callout error">${esc(e.message)}</div>`}}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',hourCycle:'h23'}).format(new Date()));return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
function viewLoading(){return `<div class="loading"><span class="spinner"></span><span>Loading…</span></div>`}
async function renderView(){const target=document.querySelector('#view-content');if(!target)return;switch(state.view){case'overview':target.innerHTML=state.user.role==='MODERATOR'?viewModeratorOverview():await viewOverview();break;case'students':target.innerHTML=await viewStudents();break;case'moderators':target.innerHTML=await viewModerators();break;case'academics':target.innerHTML=await viewAcademics();break;case'attendance':target.innerHTML=await viewAttendance();break;case'routines':case'routine':target.innerHTML=await viewRoutines();break;case'holidays':target.innerHTML=await viewHolidays();break;case'reports':target.innerHTML=await viewReports();break;case'history':target.innerHTML=await viewHistory();break;case'subjects':target.innerHTML=await viewSubjects();break;case'security':target.innerHTML=viewSecurity();break;default:target.innerHTML=empty('Section unavailable')}}
function stat(title,value,caption=''){return `<article class="card stat"><span class="label">${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(caption)}</small></article>`}
function table(headers,rows){if(!rows.length)return empty('No records found');return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function renderTodaySchedule(d){if(d.todayHoliday)return `<div class="callout warning"><b>HOLIDAY · ${esc(d.todayHoliday.name)}</b><br>${esc(d.todayHoliday.description||'No classes are scheduled for this holiday.')}</div>`;return d.today.length?d.today.map(r=>`<div class="row"><div class="row-main"><strong>${esc(r.subjectName)} ${badge(r.subjectCode)}</strong><small>${esc(r.startsAt||'')}–${esc(r.endsAt||'')} · ${esc(r.roomNumber||'Room TBA')} · ${esc(r.facultyName||'Faculty TBA')}</small></div></div>`).join(''):empty('No classes today')}
async function viewOverview(){if(state.user.role==='STUDENT'){const d=await api('/api/student/summary'),a=d.attendance;return `<div class="grid">${stat('Overall attendance',a.percentage==null?'—':`${a.percentage}%`,a.percentage==null?'No classes have been held':'Attendance across enrolled subjects')}${stat('Classes attended',a.attended,'Present marks')}${stat('Classes held',a.held,'Held classes only')}${stat('Classes missed',a.missed,'Absent marks')}${a.percentage!==null&&a.percentage<75?`<div class="span-12 callout warning"><b>Attendance below 75%.</b> ${a.classesTo75==null?'Even attending every remaining scheduled class will not reach 75%.':a.classesTo75===0?'You are currently at or above 75%.':`Attend the next ${a.classesTo75} consecutive classes to reach 75%.`}</div>`:''}<article class="card span-8"><h2>Subject attendance</h2>${d.subjects.length?d.subjects.map(s=>`<div class="row"><div class="row-main"><strong>${esc(s.name)} <small>${esc(s.code)}</small></strong><small>${s.attended}/${s.held} classes</small></div><div style="min-width:100px;text-align:right">${s.percentage==null?'—':`${s.percentage}%`}<div class="progress ${s.percentage!==null&&s.percentage<75?'low':''}"><i style="width:${s.percentage||0}%"></i></div></div></div>`).join(''):empty('No subjects enrolled')}</article><article class="card span-4"><h2>Academic profile</h2><div class="row"><span>Roll number</span><b>${esc(d.profile.rollNumber)}</b></div><div class="row"><span>Registration</span><b>${esc(d.profile.registrationNumber||'—')}</b></div><div class="row"><span>Department</span><b>${esc(d.profile.department||'—')}</b></div><div class="row"><span>Branch</span><b>${esc(d.profile.branch||'—')}</b></div><div class="row"><span>Course / semester</span><b>${esc([d.profile.course,d.profile.semester].filter(Boolean).join(' · ')||'—')}</b></div><div class="row"><span>Academic year / section</span><b>${esc([d.profile.academicYear,d.profile.section].filter(Boolean).join(' · ')||'—')}</b></div></article><article class="card span-12"><div class="section-title"><h2>Today's classes</h2><span class="mobile-note">${fmtDate(today())}</span></div>${renderTodaySchedule(d)}</article><article class="card span-12"><h2>Upcoming holidays</h2>${d.holidays.length?d.holidays.map(h=>`<div class="row"><div class="row-main"><strong>${esc(h.name)}</strong><small>${fmtDate(h.startsOn)}${h.endsOn!==h.startsOn?` – ${fmtDate(h.endsOn)}`:''} · ${esc(h.description||'')}</small></div>${badge(h.category)}</div>`).join(''):empty('No upcoming holidays')}</article></div>`}
  const d=await api('/api/dashboard');return `<div class="grid">${stat('Students',d.students,'Active student accounts')}${stat('Moderators',`${d.moderators}/5`,'Active moderators')}${stat('Subjects',d.subjects,'Active subjects')}${stat('Today’s classes',d.classesToday,'Scheduled or recorded today')}<article class="card span-8"><h2>Attendance snapshot</h2><p class="subtle">${esc(d.attendanceNote||'Attendance statistics for the current academic session.')}</p><div class="grid">${stat('Held classes',d.attendance.held)}${stat('Present marks',d.attendance.present)}${stat('Below 75%',d.attendance.lowAttendance,'Enrolled students')}</div></article><article class="card span-4"><h2>Quick actions</h2><div class="form">${button('Add a student','new-student','primary')}${button('Take attendance','go-attendance')}${button('Manage holidays','go-holidays')}</div></article><article class="card span-12"><h2>Recent activity</h2>${d.activity.length?d.activity.map(x=>`<div class="row"><div class="row-main"><strong>${esc(x.eventType.replaceAll('.',' · '))}</strong><small>${esc(x.actorName||'System')} · ${new Date(x.createdAt).toLocaleString()}</small></div></div>`).join(''):empty('No recent activity')}</article></div>`}
function viewModeratorOverview(){const p=state.user.permissions||[];return `<div class="grid"><article class="card span-8"><h2>Your assigned workspace</h2><p class="subtle">Only sections granted by the owner appear here. Protected data is checked again by the server for every request.</p>${p.length?`<div class="permissions">${[...new Set(p)].map(key=>`<span class="permission">${esc(PERMISSIONS.find(x=>x[0]===key)?.[1]||key)}</span>`).join('')}</div>`:empty('No permissions assigned','Ask the owner to grant access to the subjects and tools you need.')}</article><article class="card span-4"><h2>Quick access</h2><div class="form">${p.some(x=>['view_attendance','mark_attendance'].includes(x))?button('Open attendance','go-attendance','primary'):''}${p.includes('view_assigned_subjects')||p.includes('manage_assigned_subjects')?button('View assigned subjects','go-subjects'):''}${p.includes('view_attendance_history')?button('Attendance history','go-history'):''}${p.includes('view_routines')?button('Class routine','go-routines'):''}${p.includes('view_holidays')?button('Holidays','go-holidays'):''}</div></article></div>`}
async function viewStudents(){const d=await api('/api/students');return `<div class="section-title"><h2>Student accounts</h2><div class="row-actions">${button('CSV template','import-template','soft')+button('Import CSV','import-students','soft')}${button('Export CSV','export-students','soft')}${button('Create student','new-student','primary')}</div></div><p class="mobile-note">Safely deleted student profiles are de-identified while attendance history is retained. CSV import requires fullName, username, password, rollNumber, registrationNumber, department, course, semesterOrdinal, academicYear, and section. Department, branch, course, and academicSession values use their names.</p>${table(['Student','Roll / registration','Course','Status','Actions'],d.students.map(s=>`<tr><td><b>${esc(s.fullName)}</b><br><small>${esc(s.username)}</small></td><td>${esc(s.rollNumber)}<br><small>${esc(s.registrationNumber||'—')}</small></td><td>${esc([s.department,s.branch,s.course,s.semester].filter(Boolean).join(' · ')||'—')}</td><td>${badge(s.status,s.status==='active'?'':s.status==='suspended'?'warn':'danger')}</td><td><div class="row-actions">${s.status==='deleted'?'':`<button class="button small soft" data-action="student-edit" data-id="${esc(s.id)}">Edit</button><button class="button small soft" data-action="student-password" data-id="${esc(s.id)}">Reset password</button><button class="button small soft" data-action="student-code" data-id="${esc(s.id)}">New access code</button><button class="button small danger" data-action="student-code-revoke" data-id="${esc(s.id)}">Revoke code</button><button class="button small soft" data-action="student-promote" data-id="${esc(s.id)}">Promote to moderator</button><button class="button small ${s.status==='active'?'danger':'soft'}" data-action="student-status" data-id="${esc(s.id)}" data-status="${s.status}">${s.status==='active'?'Suspend':'Reactivate'}</button><button class="button small danger" data-action="student-delete" data-id="${esc(s.id)}">Safely delete</button>`}</div></td></tr>`))}`}
async function viewModerators(){const d=await api('/api/moderators');return `<div class="section-title"><h2>Moderators & permissions</h2>${button('Add moderator','new-moderator','primary')}</div><p class="subtle">Each moderator starts with no permissions. Changes apply to their next protected API request.</p>${d.moderators.length?d.moderators.map(m=>`<article class="card" style="margin-bottom:14px"><div class="section-title"><div><b>${esc(m.fullName)}</b> ${badge(m.status,m.status==='active'?'':'danger')}<div class="mobile-note">${esc(m.username)} · ${m.permissions.length} permissions</div></div><div class="row-actions"><button class="button small soft" data-action="moderator-edit" data-id="${esc(m.id)}">Edit</button><button class="button small soft" data-action="moderator-password" data-id="${esc(m.id)}">Reset password</button><button class="button small soft" data-action="permissions" data-id="${esc(m.id)}">Permissions</button><button class="button small ${m.status==='active'?'danger':'soft'}" data-action="moderator-status" data-id="${esc(m.id)}" data-status="${m.status}">${m.status==='active'?'Suspend':'Reactivate'}</button><button class="button small danger" data-action="moderator-delete" data-id="${esc(m.id)}">Remove</button></div></div><div class="mobile-note">${m.permissions.map(p=>esc(PERMISSIONS.find(x=>x[0]===p.permission)?.[1]||p.permission)).join(' · ')||'No permissions assigned'}</div></article>`).join(''):empty('No moderators yet')}</section>`}
async function viewAcademics(){const d=await api('/api/academics');return `<div class="grid"><article class="card span-6"><div class="section-title"><h2>Departments</h2>${button('Add department','new-department','primary small')}</div>${d.departments.length?d.departments.map(x=>`<div class="row"><div class="row-main"><b>${esc(x.name)}</b></div><div class="row-actions"><button class="button small danger" data-action="department-delete" data-id="${esc(x.id)}">Delete</button></div></div>`).join(''):empty('No departments')}</article><article class="card span-6"><div class="section-title"><h2>Branches</h2>${button('Add branch','new-branch','primary small')}</div>${d.branches.length?d.branches.map(x=>`<div class="row"><div class="row-main"><b>${esc(x.name)}</b><small>${esc(x.departmentName)}</small></div><button class="button small danger" data-action="branch-delete" data-id="${esc(x.id)}">Delete</button></div>`).join(''):empty('No branches')}</article><article class="card span-6"><div class="section-title"><h2>Courses & degrees</h2>${button('Add course','new-course','primary small')}</div>${d.courses.length?d.courses.map(x=>`<div class="row"><div class="row-main"><b>${esc(x.name)}</b><small>${esc(x.departmentName)} · ${esc(x.degree||'')}${x.branchName?' · '+esc(x.branchName):''}</small></div><button class="button small danger" data-action="course-delete" data-id="${esc(x.id)}">Delete</button></div>`).join(''):empty('No courses')}</article><article class="card span-12"><div class="section-title"><h2>Subjects</h2>${button('Add subject','new-subject','primary small')}</div>${d.subjects.length?table(['Subject','Code','Department','Course / semester','Faculty','Status',''],d.subjects.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.code)}</td><td>${esc(s.departmentName)}</td><td>${esc([s.courseName,s.semesterName].filter(Boolean).join(' · ')||'—')}</td><td>${esc(s.facultyName||'—')}</td><td>${s.active?'Active':'Inactive'}</td><td><button class="button small soft" data-action="subject-enrollments" data-id="${esc(s.id)}">Enroll students</button> <button class="button small soft" data-action="subject-edit" data-id="${esc(s.id)}">Edit</button> <button class="button small danger" data-action="subject-delete" data-id="${esc(s.id)}">Delete</button></td></tr>`)):empty('No subjects')}</article><article class="card span-12"><div class="section-title"><h2>Academic sessions</h2>${button('Add session','new-session','primary small')}</div>${d.sessions.length?d.sessions.map(s=>`<div class="row"><div class="row-main"><b>${esc(s.name)}</b><small>${fmtDate(s.startsOn)} – ${fmtDate(s.endsOn)}</small></div>${badge(s.status)} <button class="button small soft" data-action="session-edit" data-id="${esc(s.id)}">Edit</button></div>`).join(''):empty('No sessions')}</article></div>`}
async function viewSubjects(){const d=await api('/api/moderator/subjects');return `<h2>Assigned subjects</h2>${d.subjects.length?d.subjects.map(s=>`<article class="card"><b>${esc(s.name)} (${esc(s.code)})</b><div class="mobile-note">${esc(s.departmentName)} · ${esc(s.courseName||'')}</div></article>`).join(''):empty('No assigned subjects')}</article>`}
async function viewAttendance(){const d=await api('/api/attendance/options');const canMark=state.user.role==='OWNER'||d.subjects.some(s=>s.canMark);return `<div class="section-title"><h2>Attendance</h2>${canMark?button('Start a class session','start-attendance','primary'):''}</div><p class="subtle">Attendance is recorded for every enrolled student for each held class. Holidays and cancelled classes are excluded.</p>${d.subjects.length?table(['Subject','Code','Department','Enrolled',''],d.subjects.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.code)}</td><td>${esc(s.departmentName)}</td><td>${s.enrolled}</td><td>${s.canHistory?`<button class="button small soft" data-action="attendance-history" data-id="${esc(s.id)}">View history</button>`:''}</td></tr>`)):empty('No subjects available','Create a subject and enroll students to begin.')}`}
function routineDayContent(periods,weekday,edit){const selected=periods.filter(p=>p.weekday===weekday).sort((a,b)=>(a.position??0)-(b.position??0)||String(a.startsAt).localeCompare(String(b.startsAt)));if(!selected.length)return empty('No periods scheduled',`There are no routine periods for ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][weekday]}.`);return table(['Period','Subject','Code','Starts','Ends','Room','Teacher / Faculty','Class',...(edit?['Actions']:[])],selected.map(p=>`<tr><td>${Number(p.position||0)+1}</td><td>${esc(p.subjectName)}</td><td>${esc(p.subjectCode)}</td><td>${esc(p.startsAt)}</td><td>${esc(p.endsAt)}</td><td>${esc(p.roomNumber||'—')}</td><td>${esc(p.facultyName||'—')}</td><td>${esc([p.departmentName,p.courseName,p.semesterName,p.section].filter(Boolean).join(' · ')||'—')}</td>${edit?`<td class="routine-actions"><button class="button small soft" data-action="routine-up" data-id="${esc(p.periodId)}" aria-label="Move period up">↑</button> <button class="button small soft" data-action="routine-down" data-id="${esc(p.periodId)}" aria-label="Move period down">↓</button> <button class="button small soft" data-action="routine-edit" data-id="${esc(p.periodId)}">Edit</button> <button class="button small danger" data-action="routine-delete" data-id="${esc(p.periodId)}">Delete</button></td>`:''}</tr>`))}
async function viewRoutines(){if(!state.routinePeriods)state.routinePeriods=(await api('/api/routines')).periods||[];const periods=state.routinePeriods,edit=state.user.role==='OWNER'||state.user.permissions?.includes('manage_routines'),weekdays=[{name:'Monday',short:'MON',value:1},{name:'Tuesday',short:'TUE',value:2},{name:'Wednesday',short:'WED',value:3},{name:'Thursday',short:'THU',value:4},{name:'Friday',short:'FRI',value:5},{name:'Saturday',short:'SAT',value:6},{name:'Sunday',short:'SUN',value:0}],todayWeekday=new Date(`${today()}T00:00:00Z`).getUTCDay();if(state.routineWeekday===null||!weekdays.some(d=>d.value===state.routineWeekday))state.routineWeekday=todayWeekday;const selected=state.routineWeekday;return `<div class="section-title"><h2>${state.user.role==='STUDENT'?'My timetable':'Class routines'}</h2>${edit?`<div class="row-actions">${button('Copy a day','copy-routine','soft')}${button('Add period','new-routine','primary')}</div>`:''}</div><section class="card weekly-routine" aria-label="Weekly class timetable"><div class="weekday-strip" role="group" aria-label="Choose a day for the timetable">${weekdays.map(d=>`<button class="weekday-button ${selected===d.value?'selected':''} ${todayWeekday===d.value?'is-today':''}" type="button" data-routine-day="${d.value}" aria-pressed="${selected===d.value}" aria-label="${d.name}${todayWeekday===d.value?' — today':''}"><span>${d.short}</span><small>${todayWeekday===d.value?'Today':''}</small></button>`).join('')}</div><div class="routine-day-heading"><div><p class="eyebrow">Selected timetable</p><h3>${weekdays.find(d=>d.value===selected)?.name}</h3></div>${selected===todayWeekday?'<span class="badge">Today</span>':''}</div><div class="routine-table-wrap">${routineDayContent(periods,selected,edit)}</div></section>`}
function holidayCalendar(holidays){const [year,month]=today().split('-').map(Number),monthIndex=month-1,first=new Date(Date.UTC(year,monthIndex,1)),days=new Date(Date.UTC(year,monthIndex+1,0)).getUTCDate(),offset=first.getUTCDay(),heads=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<article class="card span-12"><div class="section-title"><h2>${new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric',timeZone:'UTC'}).format(first)}</h2><span class="mobile-note">College calendar · Asia/Kolkata</span></div><div class="calendar">${heads.map(x=>`<div class="day-head">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div class="day off"></div>').join('')}${Array.from({length:days},(_,i)=>{const n=i+1,date=new Date(Date.UTC(year,monthIndex,n)).toISOString().slice(0,10),holiday=holidays.find(h=>h.startsOn<=date&&h.endsOn>=date),isToday=date===today();return `<div class="day ${holiday?'holiday':''} ${isToday?'today':''}" ${holiday?`title="${esc(holiday.name)}"`:''}><b>${n}</b>${holiday?`<br><small>${esc(holiday.name)}</small>`:''}</div>`}).join('')}</div></article>`}
async function viewHolidays(){const d=await api('/api/holidays');const edit=state.user.role==='OWNER';return `<div class="section-title"><h2>College holidays</h2>${edit?button('Add holiday','new-holiday','primary'):''}</div><div class="grid">${holidayCalendar(d.holidays)}<article class="card span-12"><h2>Holiday list</h2>${d.holidays.length?table(['Holiday','Dates','Category','Description',...(edit?['Actions']:[])],d.holidays.map(h=>`<tr><td><b>${esc(h.name)}</b></td><td>${fmtDate(h.startsOn)}${h.endsOn!==h.startsOn?` – ${fmtDate(h.endsOn)}`:''}</td><td>${badge(h.category)}</td><td>${esc(h.description||'—')}</td>${edit?`<td><button class="button small soft" data-action="holiday-edit" data-id="${esc(h.id)}">Edit</button> <button class="button small danger" data-action="holiday-delete" data-id="${esc(h.id)}">Delete</button></td>`:''}</tr>`)):empty('No holidays recorded')}</article></div>`}
async function viewReports(){const [r,a]=await Promise.all([api('/api/reports'),api('/api/audit')]);return `<div class="grid">${stat('Overall attendance',r.percentage==null?'—':`${r.percentage}%`,'Present / held classes')}${stat('Classes held',r.held)}${stat('Present',r.present)}${stat('Absent',r.absent)}<article class="card span-12"><div class="section-title"><h2>Attendance by subject</h2>${button('Export CSV','export-reports','soft small')}</div>${r.subjects.length?table(['Subject','Code','Held','Present','Attendance'],r.subjects.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.code)}</td><td>${s.held}</td><td>${s.present}</td><td>${s.percentage==null?'—':`${s.percentage}%`}</td></tr>`)):empty('No attendance data')}</article><article class="card span-12"><h2>Audit log</h2>${a.logs.length?table(['When','Actor','Event','Target','Details'],a.logs.map(x=>`<tr><td>${new Date(x.createdAt).toLocaleString()}</td><td>${esc(x.actorName||'System')}</td><td>${esc(x.eventType)}</td><td>${esc([x.targetType,x.targetId].filter(Boolean).join(' · ')||'—')}</td><td>${esc(x.summary||'—')}</td></tr>`)):empty('No activity recorded')}</article></div>`}
async function viewHistory(){const d=state.user.role==='STUDENT'?await api('/api/student/attendance'):await api('/api/attendance/history');const canEdit=state.user.role==='OWNER'||state.user.permissions?.includes('edit_attendance');return `<h2>Attendance history</h2>${d.records.length?table(state.user.role==='STUDENT'?['Date','Subject','Code','Status','Room']:['Date','Subject','Student','Roll','Status',...(canEdit?['Correction']:[])],d.records.map(r=>`<tr><td>${fmtDate(r.heldOn)}</td><td>${esc(r.subjectName)}</td>${state.user.role==='STUDENT'?`<td>${esc(r.subjectCode)}</td><td>${badge(r.status,r.status==='absent'?'danger':'')}</td><td>${esc(r.roomNumber||'—')}</td>`:`<td>${esc(r.studentName||'—')}</td><td>${esc(r.rollNumber||'—')}</td><td>${badge(r.status,r.status==='absent'?'danger':'')}</td>${canEdit?`<td><button class="button small soft" data-action="attendance-correct" data-id="${esc(r.id)}" data-status="${esc(r.status)}">Correct</button></td>`:''}`}</tr>`)):empty('No attendance history')}</section>`}
function viewSecurity(){return `<div class="grid">${state.user.role==='OWNER'?`<article class="card span-6"><h2>College and owner profile</h2><form id="owner-profile" class="form">${field('collegeName','College name','text',state.user.collegeName,'required maxlength="180"')}${field('fullName','Owner full name','text',state.user.fullName,'required')}<label class="field">Username<input value="${esc(state.user.username)}" readonly></label><button class="button soft">Save profile</button></form></article>`:''}<article class="card span-6"><h2>Update your credentials</h2><p class="subtle">Choose a unique password that you do not use elsewhere.</p><form id="password-form" class="form">${field('currentPassword','Current password','password','','required autocomplete="current-password"')}${field('newPassword','New password','password','','required minlength="12" autocomplete="new-password"')}<button class="button primary">Update password</button></form><p class="mobile-note">Timezone: Asia/Kolkata · Sessions expire after 12 hours.</p></article></div>`}

async function refreshView(){if(state.view==='routine'||state.view==='routines')state.routinePeriods=null;try{await renderView()}catch(e){toast(e.message)}}
function formValues(form){return Object.fromEntries(new FormData(form))}
function csvCell(value){return `"${String(value??'').replaceAll('"','""')}"`}
function downloadCSV(filename,rows){const text='\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function parseCSV(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){value+='"';i++}else if(c==='"')quoted=false;else value+=c}else if(c==='"')quoted=true;else if(c===','){row.push(value.trim());value=''}else if(c==='\n'){row.push(value.trim());if(row.some(x=>x))rows.push(row);row=[];value=''}else if(c!=='\r')value+=c}row.push(value.trim());if(row.some(x=>x))rows.push(row);if(!rows.length)return[];const headers=rows.shift().map(x=>x.replace(/^\ufeff/,'').trim().toLowerCase());return rows.map(values=>Object.fromEntries(headers.map((h,i)=>[h,values[i]||''])))}
function downloadStudentTemplate(){downloadCSV('edutrack-student-import-template.csv',[['fullName','username','password','rollNumber','registrationNumber','department','branch','course','semesterOrdinal','academicYear','section','academicSession']])}
async function exportStudents(){try{const {students}=await api('/api/students');downloadCSV(`edutrack-students-${today()}.csv`,[['fullName','username','rollNumber','registrationNumber','department','branch','course','semester','academicYear','section','status'],...students.map(s=>[s.fullName,s.username,s.rollNumber,s.registrationNumber,s.department,s.branch,s.course,s.semester,s.academicYear,s.section,s.status])])}catch(e){toast(e.message)}}
async function exportReports(){try{const d=await api('/api/reports');downloadCSV(`edutrack-attendance-${today()}.csv`,[['subject','code','classesHeld','present','attendancePercent'],...d.subjects.map(s=>[s.name,s.code,s.held,s.present,s.percentage??''])])}catch(e){toast(e.message)}}
async function importStudents(){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const rows=parseCSV(await file.text());if(!rows.length)throw new Error('The CSV file is empty.');const academic=await api('/api/academics'),byName=(list,name)=>list.find(x=>x.name?.toLowerCase()===String(name||'').trim().toLowerCase());const payload=rows.map((r,i)=>{const department=byName(academic.departments,r.department),branch=academic.branches.find(x=>x.name.toLowerCase()===String(r.branch||'').trim().toLowerCase()&&x.departmentId===department?.id),course=academic.courses.find(x=>x.name.toLowerCase()===String(r.course||'').trim().toLowerCase()&&x.departmentId===department?.id),session=byName(academic.sessions,r.academicsession||r.session);if(!department||!course)throw new Error(`Row ${i+2}: department or course name was not found.`);return{fullName:r.fullname,username:r.username,password:r.password,rollNumber:r.rollnumber,registrationNumber:r.registrationnumber,departmentId:department.id,branchId:branch?.id||'',courseId:course.id,semesterOrdinal:r.semesterordinal,academicSessionId:session?.id||'',academicYear:r.academicyear,section:r.section}});const result=await api('/api/students/import',{method:'POST',body:{rows:payload}});const codes=result.created.map(s=>`<tr><td>${esc(s.fullName)}</td><td>${esc(s.username)}</td><td>${esc(s.rollNumber)}</td><td><code>${esc(s.accessCode)}</code></td></tr>`).join('');await modalForm('Student access codes — save now',`<p>These individual codes are shown once. Keep them private and share each code with the matching student through a secure channel.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Roll</th><th>Access code</th></tr></thead><tbody>${codes}</tbody></table></div>`,'Done');toast(`${result.created.length} students imported`);await refreshView()}catch(e){toast(e.message)}};input.click()}
async function createStudent(){const d=await api('/api/academics');const content=field('fullName','Full name','text','','required')+field('username','Username','text','','required minlength="3"')+field('password','Initial password','password','','required minlength="12" autocomplete="new-password"')+field('rollNumber','Roll number','text','','required')+field('registrationNumber','Registration number','text','','required')+selectField('departmentId','Department',d.departments.map(x=>({value:x.id,label:x.name})),'','required')+selectField('branchId','Branch',d.branches.map(x=>({value:x.id,label:`${x.name} · ${x.departmentName}`})))+selectField('courseId','Course',d.courses.map(x=>({value:x.id,label:`${x.name} · ${x.departmentName}`})),'','required')+field('semesterOrdinal','Semester number','number','','required min="1"')+selectField('academicSessionId','Academic session',d.sessions.filter(x=>x.status==='active').map(x=>({value:x.id,label:x.name})))+field('academicYear','Academic year','text','','required')+field('section','Section / class','text','','required');const v=await modalForm('Create student account',content,'Create student');if(!v)return;try{const out=await api('/api/students',{method:'POST',body:v});state.view='students';await render();await modalForm('Student access code',`<p>Share this individual code with <b>${esc(out.student.fullName)}</b> through a secure channel. It will only be shown once.</p><div class="callout"><code>${esc(out.accessCode)}</code></div><p class="mobile-note">The code is stored as a hash and cannot be recovered later. Generate a replacement if it is lost.</p>`,'Done');await render()}catch(e){toast(e.message)}}
async function editStudent(id){const {students}=await api('/api/students');const s=students.find(x=>x.id===id);if(!s)return;const d=await api('/api/academics');const content=field('fullName','Full name','text',s.fullName,'required')+field('rollNumber','Roll number','text',s.rollNumber,'required')+field('registrationNumber','Registration number','text',s.registrationNumber||'','required')+selectField('departmentId','Department',d.departments.map(x=>({value:x.id,label:x.name})),s.departmentId,'required')+selectField('branchId','Branch',d.branches.map(x=>({value:x.id,label:`${x.name} · ${x.departmentName}`})),s.branchId)+selectField('courseId','Course',d.courses.map(x=>({value:x.id,label:`${x.name} · ${x.departmentName}`})),s.courseId,'required')+field('semesterOrdinal','Semester number','number',s.semesterOrdinal||'','required min="1"')+field('academicYear','Academic year','text',s.academicYear||'','required')+field('section','Section','text',s.section||'','required');const v=await modalForm(`Edit ${s.fullName}`,content);if(!v)return;try{await api(`/api/students/${encodeURIComponent(id)}`,{method:'PATCH',body:v});toast('Student updated');await refreshView()}catch(e){toast(e.message)}}
async function resetStudentPassword(id){const v=await modalForm('Reset student password',field('password','New temporary password','password','','required minlength="12" autocomplete="new-password"'),'Reset password');if(!v)return;try{await api(`/api/students/${encodeURIComponent(id)}/password`,{method:'POST',body:v});toast('Password reset. Share it securely with the student.')}catch(e){toast(e.message)}}
async function rotateCode(id){const v=await modalForm('Issue replacement access code',field('expiresAt','Expiry date (optional)','date')+'<p class="mobile-note">The current code will be revoked immediately.</p>','Generate code');if(!v)return;try{const out=await api(`/api/students/${encodeURIComponent(id)}/access-code`,{method:'POST',body:v});await modalForm('New student access code',`<p>This code is shown once.</p><div class="callout"><code>${esc(out.accessCode)}</code></div>`,'Done')}catch(e){toast(e.message)}}
async function createModerator(){const v=await modalForm('Create moderator',field('fullName','Full name','text','','required')+field('username','Username','text','','required minlength="3"')+field('password','Initial password','password','','required minlength="12" autocomplete="new-password"'),'Create moderator');if(!v)return;try{const out=await api('/api/moderators',{method:'POST',body:v});toast(`Moderator created: ${out.moderator.username}. Assign permissions separately.`);await refreshView()}catch(e){toast(e.message)}}
async function editModerator(id){const d=await api('/api/moderators'),m=d.moderators.find(x=>x.id===id);if(!m)return;const v=await modalForm('Edit moderator',field('fullName','Full name','text',m.fullName,'required')+field('username','Username','text',m.username,'required minlength="3"'));if(!v)return;try{await api(`/api/moderators/${encodeURIComponent(id)}`,{method:'PATCH',body:v});toast('Moderator updated');await refreshView()}catch(e){toast(e.message)}}
async function resetModeratorPassword(id){const v=await modalForm('Reset moderator password',field('password','New temporary password','password','','required minlength="12" autocomplete="new-password"'),'Reset password');if(!v)return;try{await api(`/api/moderators/${encodeURIComponent(id)}/password`,{method:'POST',body:v});toast('Moderator password reset. Share it securely.')}catch(e){toast(e.message)}}
async function editPermissions(id){const [d,academic]=await Promise.all([api('/api/moderators'),api('/api/academics')]);const m=d.moderators.find(x=>x.id===id);if(!m)return;const known=m.permissions;const content=`<p class="subtle">Choose permissions separately. Set a permission to all subjects or restrict it to selected subjects. Changes apply immediately.</p>${PERMISSIONS.map(([key,label])=>{const rows=known.filter(p=>p.permission===key),global=rows.some(p=>p.scopeType==='global'),ids=rows.filter(p=>p.scopeType==='subject').map(p=>p.scopeId);return `<div class="card" style="padding:12px;box-shadow:none"><label class="permission" style="border:0;padding:2px"><input type="checkbox" name="permissions" value="${key}" ${rows.length?'checked':''}>${esc(label)}</label><label class="field">Scope<select name="scope-${key}"><option value="global" ${global||!ids.length?'selected':''}>All subjects</option><option value="subject" ${ids.length&&!global?'selected':''}>Selected subjects</option></select></label><label class="field">Subjects <select name="subjects-${key}" multiple size="3">${academic.subjects.map(s=>`<option value="${esc(s.id)}" ${ids.includes(s.id)?'selected':''}>${esc(s.name)} · ${esc(s.code)}</option>`).join('')}</select></label></div>`}).join('')}`;const values=await modalForm(`Permissions · ${m.fullName}`,content,'Save permissions');if(!values)return;const permissions=[];for(const input of dialog.querySelectorAll('input[name=permissions]:checked')){const key=input.value,scope=dialog.querySelector(`[name="scope-${key}"]`)?.value||'global';if(scope==='global')permissions.push({permission:key,scopeType:'global',scopeId:''});else for(const opt of dialog.querySelector(`[name="subjects-${key}"]`)?.selectedOptions||[])permissions.push({permission:key,scopeType:'subject',scopeId:opt.value})}try{await api(`/api/moderators/${encodeURIComponent(id)}/permissions`,{method:'PUT',body:{permissions}});toast('Permissions updated');await refreshView()}catch(e){toast(e.message)}}
async function promoteStudent(id){try{const [d,students]=await Promise.all([api('/api/academics'),api('/api/students')]),student=students.students.find(x=>x.id===id);if(!student)return;const content=`<p class="subtle">${esc(student.fullName)} will keep the same account and academic history. Select the moderator permissions before confirming.</p>${PERMISSIONS.map(([key,label])=>`<div class="card" style="padding:12px;margin:8px 0;box-shadow:none"><label class="permission" style="border:0;padding:2px"><input type="checkbox" name="permissions" value="${key}">${esc(label)}</label><label class="field">Scope<select name="scope-${key}"><option value="global">All subjects</option><option value="subject">Selected subjects</option></select></label><label class="field">Subjects <select name="subjects-${key}" multiple size="3">${d.subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.code)}</option>`).join('')}</select></label></div>`).join('')}`;if(!await modalForm('Promote student to moderator',content,'Promote'))return;const permissions=[];for(const input of dialog.querySelectorAll('input[name=permissions]:checked')){const key=input.value,scope=dialog.querySelector(`[name="scope-${key}"]`)?.value||'global';if(scope==='global')permissions.push({permission:key,scopeType:'global',scopeId:''});else{const selected=[...(dialog.querySelector(`[name="subjects-${key}"]`)?.selectedOptions||[])];if(!selected.length){toast(`Choose at least one subject for ${PERMISSIONS.find(x=>x[0]===key)?.[1]||key}.`);return}for(const opt of selected)permissions.push({permission:key,scopeType:'subject',scopeId:opt.value})}}await api(`/api/students/${encodeURIComponent(id)}/promote`,{method:'POST',body:{permissions}});toast(`${student.fullName} is now a moderator`);state.view='moderators';await render()}catch(e){toast(e.message)}}
