async function startAttendance(){const d=await api('/api/attendance/options');const subject=await modalForm('Choose class',selectField('subjectId','Subject',d.subjects.filter(x=>x.canMark!==false).map(x=>({value:x.id,label:`${x.name} · ${x.code}`})))+field('heldOn','Class date','date',today(),'required')+field('startsAt','Start time','time','','required')+field('endsAt','End time','time','','required')+field('roomNumber','Room number'),'Continue');if(!subject)return;try{const roster=await api(`/api/attendance/roster?subjectId=${encodeURIComponent(subject.subjectId)}&date=${encodeURIComponent(subject.heldOn)}`);let overrideHoliday=false;if(roster.holiday&&!roster.overrideRequired){toast(`Holiday: ${roster.holiday.name}`);return}if(roster.holiday&&roster.overrideRequired){if(!await confirmDialog('Mark an exceptional class on a holiday?',`${roster.holiday.name} is recorded for this date. This owner override will be written to the audit log.`,'Confirm class',true))return;overrideHoliday=true}if(roster.existing){toast('Attendance already exists for this subject and date.');return}const entries=roster.students.map(s=>({id:s.id,name:s.fullName,roll:s.rollNumber,status:''}));const dialogHTML=`<div class="mobile-note">Mark every enrolled student. The session cannot be saved with unmarked students.</div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Mark</th></tr></thead><tbody>${entries.map(s=>`<tr data-student="${esc(s.id)}"><td>${esc(s.name)}<br><small>${esc(s.roll)}</small></td><td><select class="control attendance-status" aria-label="Attendance for ${esc(s.name)}"><option value="">Choose…</option><option value="present">Present</option><option value="absent">Absent</option></select></td></tr>`).join('')}</tbody></table></div>`;const vals=await modalForm(`Attendance · ${fmtDate(subject.heldOn)}`,dialogHTML,'Save class');if(!vals)return;const marks=[...dialog.querySelectorAll('tbody tr')].map(tr=>({studentId:tr.dataset.student,status:tr.querySelector('select').value}));if(marks.some(m=>!m.status)){toast('Choose an attendance status for every enrolled student.');return}await api('/api/attendance/session',{method:'POST',body:{...subject,overrideHoliday,entries:marks}});toast('Class attendance saved');await refreshView()}catch(e){toast(e.message)}}
async function attendanceHistory(subjectId){try{const d=await api(`/api/attendance/history?subjectId=${encodeURIComponent(subjectId)}`),owner=state.user.role==='OWNER';await modalForm('Subject attendance history',d.records.length?table(['Date','Held','Present','Absent',...(owner?['Actions']:[])],d.records.map(x=>`<tr><td>${fmtDate(x.heldOn)}</td><td>${x.held}</td><td>${x.present}</td><td>${x.absent}</td>${owner?`<td><button class="button small danger" data-action="cancel-session" data-id="${esc(x.id)}">Cancel class</button></td>`:''}</tr>`)):empty('No class sessions'),'Close')}catch(e){toast(e.message)}}
async function moveRoutine(id,delta){try{const d=await api('/api/routines'),p=d.periods.find(x=>x.periodId===id);if(!p)return;const group=d.periods.filter(x=>x.routineId===p.routineId).sort((a,b)=>a.position-b.position),index=group.findIndex(x=>x.periodId===id),next=index+delta;if(next<0||next>=group.length)return;[group[index],group[next]]=[group[next],group[index]];await api('/api/routines/reorder',{method:'PUT',body:{routineId:p.routineId,periodIds:group.map(x=>x.periodId)}});await refreshView()}catch(e){toast(e.message)}}
async function editRoutine(id){const d=await api('/api/routines'),p=d.periods.find(x=>x.periodId===id);if(!p)return;const v=await modalForm(`Edit ${p.subjectName}`,field('startsAt','Start time','time',p.startsAt,'required')+field('endsAt','End time','time',p.endsAt,'required')+field('roomNumber','Room number','text',p.roomNumber||'')+field('facultyName','Faculty name','text',p.facultyName||'')+textareaField('notes','Notes',p.notes||'')+'<p class="mobile-note">Changes receive a new effective routine version if they affect a past timetable.</p>');if(!v)return;try{await api(`/api/routines/periods/${encodeURIComponent(id)}`,{method:'PATCH',body:v});toast('Routine period updated');await refreshView()}catch(e){toast(e.message)}}
async function copyRoutine(){const d=await api('/api/routines'),groups=new Map();for(const p of d.periods){if(!groups.has(p.routineId))groups.set(p.routineId,{id:p.routineId,day:p.weekday,weekdayName:p.weekdayName,items:[]});groups.get(p.routineId).items.push(p.subjectName)}const options=[...groups.values()].map(g=>({value:g.id,label:`${g.weekdayName} · ${g.items.slice(0,3).join(', ')}${g.items.length>3?'…':''}`}));if(!options.length){toast('Create at least one routine day before copying it.');return}const v=await modalForm('Copy a day to another weekday',selectField('sourceRoutineId','Copy from',options,'','required')+selectField('targetWeekday','Copy to',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>({value:i,label:x})),'','required')+field('effectiveFrom','Effective from','date',today(),'required')+'<p class="mobile-note">This creates a dated routine version for the selected class. Existing history is retained.</p>','Copy day');if(!v)return;try{await api('/api/routines/copy',{method:'POST',body:v});toast('Routine day copied');await refreshView()}catch(e){toast(e.message)}}
async function addRoutine(){const d=await api('/api/routines/options');const v=await modalForm('Add routine period',selectField('departmentId','Department',d.departments.map(x=>({value:x.id,label:x.name})))+selectField('courseId','Course',d.courses.map(x=>({value:x.id,label:x.name})))+selectField('subjectId','Subject',d.subjects.map(x=>({value:x.id,label:`${x.name} · ${x.code}`})))+field('semesterName','Semester label','text','','required')+field('section','Section')+selectField('weekday','Day of week',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>({value:i,label:x})))+field('effectiveFrom','Effective from','date',today(),'required')+field('startsAt','Start time','time','','required')+field('endsAt','End time','time','','required')+field('roomNumber','Room number')+field('facultyName','Faculty name')+textareaField('notes','Notes'));if(!v)return;try{await api('/api/routines',{method:'POST',body:v});toast('Routine period saved');await refreshView()}catch(e){toast(e.message)}}
async function addHoliday(existing){const v=await modalForm(existing?'Edit holiday':'Add college holiday',field('name','Holiday name','text',existing?.name||'','required')+field('startsOn','Starts on','date',existing?.startsOn||today(),'required')+field('endsOn','Ends on','date',existing?.endsOn||today(),'required')+selectField('category','Category',['national','festival','college','closure','emergency'].map(x=>({value:x,label:x[0].toUpperCase()+x.slice(1)})),existing?.category||'college')+textareaField('description','Description',existing?.description||''),existing?'Save changes':'Add holiday');if(!v)return;try{await api(existing?`/api/holidays/${encodeURIComponent(existing.id)}`:'/api/holidays',{method:existing?'PATCH':'POST',body:v});toast('Holiday saved');await refreshView()}catch(e){toast(e.message)}}
