async function delegatedAction(action,id,el){try{if(action==="student-promote")return promoteStudent(id);switch(action){case'export-reports':return exportReports();case'import-template':return downloadStudentTemplate();case'import-students':return importStudents();case'export-students':return exportStudents();case'new-student':return createStudent();case'student-edit':return editStudent(id);case'student-password':return resetStudentPassword(id);case'student-code':return rotateCode(id);case'student-code-revoke':if(await confirmDialog('Revoke student access code?','This immediately prevents student login until a replacement code is issued.','Revoke code',true)){await api(`/api/students/${encodeURIComponent(id)}/access-code`,{method:'DELETE'});toast('Access code revoked');return}return;case'student-status':{const status=el.dataset.status==='active'?'suspended':'active';await api(`/api/students/${encodeURIComponent(id)}`,{method:'PATCH',body:{status}});toast(`Student ${status}`);return refreshView()}case'student-delete':if(await confirmDialog('Safely delete student account?','The account will be de-identified and disabled. Historical attendance entries remain available in reports.','Safely delete',true)){await api(`/api/students/${encodeURIComponent(id)}`,{method:'DELETE'});toast('Student profile de-identified');return refreshView()}return;case'moderator-edit':return editModerator(id);case'moderator-password':return resetModeratorPassword(id);case'new-moderator':return createModerator();case'permissions':return editPermissions(id);case'moderator-status':{await api(`/api/moderators/${encodeURIComponent(id)}`,{method:'PATCH',body:{status:el.dataset.status==='active'?'suspended':'active'}});return refreshView()}case'moderator-delete':if(await confirmDialog('Remove moderator?','This removes the moderator account and its permissions.','Remove',true)){const result=await api(`/api/moderators/${encodeURIComponent(id)}`,{method:'DELETE'});if(result.restoredStudent)await showStudentAccessCode(result.accessCode);return refreshView()}return;case'new-department':return addDepartment();case'new-branch':return addBranch();case'new-course':return addCourse();case'subject-edit':return editSubject(id);case'new-subject':return addSubject();case'new-session':return addSession();case'session-edit':return editSession(id);case'subject-enrollments':return enrollStudents(id);case'department-delete':case'branch-delete':case'course-delete':case'subject-delete':if(await confirmDialog('Delete academic record?','Existing academic history may prevent deletion.','Delete',true)){const endpoint=action.startsWith('department')?'departments':action.startsWith('branch')?'branches':action.startsWith('course')?'courses':'subjects';await api(`/api/${endpoint}/${encodeURIComponent(id)}`,{method:'DELETE'});return refreshView()}return;case'attendance-correct':return correctAttendance(id,el.dataset.status);case'start-attendance':return startAttendance();case'attendance-history':return attendanceHistory(id);case'cancel-session':if(dialog.open)dialog.close();if(await confirmDialog('Cancel class session?','Cancelled sessions are excluded from attendance calculations. Existing marks are retained for audit.','Cancel class',true)){await api(`/api/class-sessions/${encodeURIComponent(id)}`,{method:'PATCH',body:{status:'cancelled'}});toast('Class cancelled');return refreshView()}return;case'routine-up':return moveRoutine(id,-1);case'routine-down':return moveRoutine(id,1);case'routine-edit':return editRoutine(id);case'copy-routine':return copyRoutine();case'new-routine':return addRoutine();case'routine-delete':if(await confirmDialog('Delete routine period?','This creates a new effective routine version for future dates so the historical timetable stays available.','Delete',true)){await api(`/api/routines/periods/${encodeURIComponent(id)}`,{method:'DELETE'});return refreshView()}return;case'new-holiday':return addHoliday();case'holiday-edit':{const d=await api('/api/holidays');return addHoliday(d.holidays.find(x=>x.id===id))}case'holiday-delete':if(await confirmDialog('Delete holiday?','This removes the holiday from the calendar.','Delete',true)){await api(`/api/holidays/${encodeURIComponent(id)}`,{method:'DELETE'});return refreshView()}return;case'go-subjects':state.view='subjects';return render();case'go-history':state.view='history';return render();case'go-routines':state.view='routine';return render();case'go-attendance':state.view='attendance';return render();case'go-holidays':state.view='holidays';return render()}}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const day=e.target.closest('[data-routine-day]');if(day){state.routineWeekday=Number(day.dataset.routineDay);renderView();return}const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(action==='close-dialog'){dialog.close();return}delegatedAction(action,target.dataset.id,target)});
document.querySelector('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',body:{}})}catch{}state.user=null;state.csrf='';state.view='overview';state.routinePeriods=null;state.routineWeekday=null;renderLogin()});
document.querySelector('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('edutrack-theme',state.theme);applyTheme()});
document.addEventListener('submit',async e=>{if(e.target.id==='password-form'){e.preventDefault();try{await api('/api/me/password',{method:'POST',body:formValues(e.target)});toast('Password updated');e.target.reset()}catch(err){toast(err.message)}}else if(e.target.id==='owner-profile'){e.preventDefault();try{const r=await api('/api/me',{method:'PATCH',body:formValues(e.target)});state.user.fullName=r.fullName;state.user.collegeName=r.collegeName;document.querySelector('#identity').textContent=r.fullName;document.querySelector('#college-name').textContent=r.collegeName;toast('College profile updated')}catch(err){toast(err.message)}}});
state.historyFilters ||= {from:'',to:'',subjectId:'',student:''};
state.reportFilters ||= {from:'',to:'',subjectId:'',studentId:''};
const classroomPendingMarks=new Map();
window.addEventListener('beforeunload',event=>{if(classroomPendingMarks.size){event.preventDefault();event.returnValue=''}});

function classroomStatus(status){const labels={live:'LIVE',upcoming:'UPCOMING','in-progress':'IN PROGRESS',scheduled:'SCHEDULED',completed:'COMPLETED','not-recorded':'NOT RECORDED'};return badge(labels[status]||status,status==='live'?'success':status==='not-recorded'?'warning':'')}
function classroomAction(label,action,attrs='',kind='soft'){return `<button type="button" class="button small ${kind}" data-classroom-action="${esc(action)}" ${attrs}>${esc(label)}</button>`}
function classCard(item,{scheduled=false,canMark=false}={}){
  const dateLabel=fmtDate(item.heldOn||today()),time=`${item.startsAt||'—'}${item.endsAt?`–${item.endsAt}`:''}`,subject=esc(item.subjectName||'Class');
  const controls=scheduled&&!item.sessionId?(canMark?classroomAction(item.status==='not-recorded'?'Record attendance':'Start classroom','start',`data-subject="${esc(item.subjectId||'')}" data-start="${esc(item.startsAt||'')}" data-end="${esc(item.endsAt||'')}" data-room="${esc(item.roomNumber||'')}" data-record="${item.status==='not-recorded'}"`,item.status==='not-recorded'?'soft':'primary'):''):
    item.id?(canMark?`${classroomAction(item.status==='live'?'Open attendance':'View attendance','open',`data-id="${esc(item.id)}"`,item.status==='live'?'primary':'soft')}${item.status==='live'?classroomAction('End class','end',`data-id="${esc(item.id)}"`,'danger'):''}${classroomAction('Download report','download',`data-id="${esc(item.id)}"`,'quiet')}${classroomAction('Edit details','edit',`data-id="${esc(item.id)}"`,'quiet')}`:'') : '';
  return `<article class="classroom-card"><div class="classroom-card-main"><div class="classroom-card-title"><strong>${subject}</strong>${classroomStatus(item.status)}</div><p>${esc(time)} · ${esc(item.roomNumber||'Room TBA')}</p><small>${esc(item.teacherName||item.facultyName||'Teacher not listed')} · ${dateLabel}</small></div><div class="classroom-card-actions">${controls}</div></article>`;
}

routineDayContent = function routineDayContent(periods,weekday,edit){
  const selected=periods.filter(period=>period.weekday===weekday).sort((a,b)=>(a.position??0)-(b.position??0)||String(a.startsAt).localeCompare(String(b.startsAt)));
  if(!selected.length)return empty('No periods scheduled',`There are no routine periods for ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][weekday]}.`);
  return table(['Period','Subject / break','Code','Starts','Ends','Length','Room','Teacher / Faculty','Class',...(edit?['Actions']:[])],selected.map(period=>{
    const isBreak=period.periodType==='break',duration=Math.max(0,(Number(period.endsAt?.slice(0,2))*60+Number(period.endsAt?.slice(3,5)))-(Number(period.startsAt?.slice(0,2))*60+Number(period.startsAt?.slice(3,5))));
    return `<tr class="${isBreak?'recess-row':''}"><td>${Number(period.position||0)+1}</td><td>${isBreak?badge('RECESS','recess-badge'):esc(period.subjectName)}</td><td>${isBreak?'—':esc(period.subjectCode)}</td><td>${esc(period.startsAt)}</td><td>${esc(period.endsAt)}</td><td>${duration} min</td><td>${esc(period.roomNumber||'—')}</td><td>${esc(period.facultyName||'—')}</td><td>${esc([period.departmentName,period.courseName,period.semesterName,period.section].filter(Boolean).join(' · ')||'—')}</td>${edit?`<td class="routine-actions"><button class="button small soft" data-action="routine-up" data-id="${esc(period.periodId)}" aria-label="Move period up">↑</button> <button class="button small soft" data-action="routine-down" data-id="${esc(period.periodId)}" aria-label="Move period down">↓</button> <button class="button small soft" data-action="routine-edit" data-id="${esc(period.periodId)}">Edit</button> <button class="button small danger" data-action="routine-delete" data-id="${esc(period.periodId)}">Delete</button></td>`:''}</tr>`;
  }));
};

